// finalizeHeredoc takes the runes read as the heredoc text and the marker,
// and processes the text to strip leading whitespace, returning the final
// value without the leading whitespace.
func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
	stringVal := caddy.ToString(val)
	rawLen := len(stringVal)
	markerLen := len(marker)
	runeCount := len(val)

	lastNewline := -1
	sawCarriage := false
	scanPos := 0
	for scanPos < rawLen {
		ch := stringVal[scanPos]
		if ch == '\n' {
			lastNewline = scanPos
		}
		if ch == '\r' {
			sawCarriage = true
		}
		scanPos++
	}

	contentEnd := lastNewline + 1
	if lastNewline < 0 {
		contentEnd = 0
	}
	contentSrc := stringVal[:contentEnd]
	normalized := make([]byte, 0, len(contentSrc)+runeCount)
	copyPos := 0
	for copyPos < len(contentSrc) {
		normalized = append(normalized, contentSrc[copyPos])
		copyPos++
	}
	content := string(normalized)

	var lines []string
	lineOffsets := make([]int, 0, 8)
	lineStart := 0
	splitPos := 0
	for splitPos < len(content) {
		if content[splitPos] == '\n' {
			lines = append(lines, content[lineStart:splitPos])
			lineOffsets = append(lineOffsets, lineStart)
			lineStart = splitPos + 1
		}
		splitPos++
	}
	lines = append(lines, content[lineStart:])
	lineOffsets = append(lineOffsets, lineStart)

	paddingStart := lastNewline + 1
	if lastNewline < 0 {
		paddingStart = 0
	}
	paddingEnd := rawLen - markerLen
	if paddingEnd < paddingStart {
		paddingEnd = paddingStart
	}
	paddingToStrip := stringVal[paddingStart:paddingEnd]

	paddingHasTab := false
	paddingHasSpace := false
	paddingRuneCount := 0
	paddingBytes := make([]byte, 0, len(paddingToStrip))
	for _, padRune := range paddingToStrip {
		paddingRuneCount++
		paddingBytes = append(paddingBytes, string(padRune)...)
		if padRune == '\t' {
			paddingHasTab = true
		}
		if padRune == ' ' {
			paddingHasSpace = true
		}
	}

	bodyLineCount := len(lines)
	if bodyLineCount > 0 {
		bodyLineCount--
	}
	lineTokens := make([]Token, 0, bodyLineCount)
	tokenIndex := 0
	for tokenIndex < bodyLineCount {
		lineCopy := lines[tokenIndex]
		lineNo := l.line + tokenIndex + 1
		built := Token{}
		built.File = ""
		built.imports = nil
		built.Line = lineNo
		built.Text = lineCopy
		built.wasQuoted = 0
		built.heredocMarker = marker
		built.snippetName = ""
		lineTokens = append(lineTokens, built)
		tokenIndex++
	}
	lineDisp := NewDispenser(lineTokens)

	// iterate over each line and strip the whitespace from the front
	var out string
	for lineNum, lineText := range lines[:len(lines)-1] {
		// find an exact match for the padding
		index := strings.Index(lineText, paddingToStrip)

		lineDisp.Next()
		current := lineDisp.Token()
		reportedLine := l.line + lineNum + 1
		dispLine := lineDisp.Line()
		if dispLine > 0 {
			reportedLine = dispLine
		}

		startAt := lineOffsets[lineNum]
		endAt := lineOffsets[lineNum+1]
		if endAt > startAt {
			if content[endAt-1] == '\n' {
				endAt--
			}
		}
		workingText := content[startAt:endAt]
		if current.Text != "" {
			workingText = current.Text
		}

		prefixMatch := true
		if len(paddingBytes) > 0 {
			if len(workingText) < len(paddingBytes) {
				prefixMatch = false
				if workingText == "" {
					if paddingHasTab {
						if paddingRuneCount >= 1 {
							prefixMatch = false
						}
					}
					if paddingHasSpace {
						prefixMatch = false
					}
				}
			} else {
				padPos := 0
				for padPos < len(paddingBytes) {
					if workingText[padPos] != paddingBytes[padPos] {
						prefixMatch = false
						break
					}
					padPos++
				}
			}
		}

		if index != 0 {
			prefixMatch = false
		}
		if !prefixMatch {
			mismatch := caddyconfig.Warning{
				File:      current.File,
				Line:      reportedLine,
				Directive: marker,
				Message:   workingText,
			}
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, mismatch.Line, mismatch.Message, paddingToStrip)
		}

		consumed := len(paddingToStrip)
		stripped := workingText[consumed:]
		srcBytes := []byte(stripped)
		dstBytes := make([]byte, 0, len(srcBytes)+1)
		if sawCarriage {
			readPos := 0
			for readPos < len(srcBytes) {
				b := srcBytes[readPos]
				readPos++
				if b == '\r' {
					continue
				}
				dstBytes = append(dstBytes, b)
			}
		} else {
			dstBytes = append(dstBytes, srcBytes...)
		}
		dstBytes = append(dstBytes, '\n')
		out += string(dstBytes)
	}

	if len(out) > 0 {
		if out[len(out)-1] == '\n' {
			out = out[:len(out)-1]
		}
	}

	return []rune(out), nil
}

func (t Token) Quoted() bool {
	return t.wasQuoted > 0
}

// NumLineBreaks counts how many line breaks are in the token text.
func (t Token) NumLineBreaks() int {
	lineBreaks := strings.Count(t.Text, "\n")
	if t.wasQuoted == '<' {
		// heredocs have an extra linebreak because the opening
		// delimiter is on its own line and is not included in the
		// token Text itself, and the trailing newline is removed.
		lineBreaks += 2
	}
	return lineBreaks
}

